CREATE OR REPLACE FUNCTION public.icash_apply_prepaid_purchase(p_order uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.icash_funding_orders;funded bigint;a public.icash_accounts;
begin
 select * into o from public.icash_funding_orders where id=p_order for update;
 if not found or o.mode<>'live' or o.state<>'paid' or o.account_id is null or o.credited_at is null then return false;end if;
 if o.prepaid_applied_at is not null then return true;end if;
 if not exists(select 1 from public.icash_funding_consents c where c.order_id=o.id and c.version='work-credits-2026-10-03.1' and c.account_id=o.account_id and c.price_cents=o.price_cents and c.credit_cents=o.credit_cents) then return false;end if;
 select * into a from public.icash_accounts where id=o.account_id for update;
 if exists(select 1 from public.icash_daily_plans where account_id=a.id and mode='live' and state<>'stopped') then return false;end if;
 if exists(select 1 from public.icash_billing_reviews where account_id=a.id and resolved_at is null) or not public.icash_membership_work_allowed(a.id) then return false;end if;
 perform 1 from public.icash_wallets where account_id=a.id for update;
 select coalesce(sum(credit_cents),0) into funded from public.icash_funding_orders where account_id=a.id and mode='live' and state='paid' and credited_at is not null;
 if funded<=0 or funded>100000000 then return false;end if;
 insert into public.icash_spend_activations(account_id,enabled,customer_cap_cents) values(a.id,true,funded)
 on conflict(account_id) do update set enabled=true,customer_cap_cents=excluded.customer_cap_cents;
 update public.icash_accounts set billing_model=case when billing_model='legacy' then 'prepaid' else billing_model end,daily_limit_cents=funded,bot_paused=false where id=a.id;
 update public.icash_funding_orders set prepaid_applied_at=now(),pacing_applied_at=now() where id=o.id;
 -- Provider/channel, identity, contact, cost, offer and contract authority checks still run at dispatch.
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_queue_text(p_account uuid, p_thread uuid, p_key uuid, p_body text, p_assets uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m public.icash_text_messages;urls jsonb;total bigint;
begin
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account;
 if not found or not exists(select 1 from public.icash_deal_files where id=t.deal_id and account_id=p_account) then raise exception 'Thread not available';end if;
 if length(trim(p_body))=0 and cardinality(p_assets)=0 then raise exception 'Message required';end if;
 if length(p_body)>1000 or cardinality(p_assets)>3 then raise exception 'Message too large';end if;
 -- One SMS segment per reviewed rate; MMS has its own independent rate.
 if cardinality(p_assets)=0 and (length(p_body)>160 or (p_body ~ '[^A-Za-z0-9 .,!?]' and length(p_body)>35)) then raise exception 'Shorten the message';end if;
 select coalesce(jsonb_agg(url order by id),'[]'),coalesce(sum(bytes),0) into urls,total from public.icash_text_assets where id=any(p_assets) and account_id=p_account and deal_id=t.deal_id and verified_until>now();
 if jsonb_array_length(urls)<>cardinality(p_assets) or total>5000000 then raise exception 'Verified attachments required';end if;
 insert into public.icash_text_messages(thread_id,account_id,direction,body,asset_ids,attachments,state,request_key) values(t.id,p_account,'outgoing',p_body,p_assets,urls,'ready',p_key) on conflict(request_key) do nothing;
 select * into m from public.icash_text_messages where request_key=p_key;
 -- Insert uses the caller's idempotency key below; no cross-account lookup may return an ID.
 if m.id is null then raise exception 'Message key missing';end if;
 if m.account_id<>p_account or m.thread_id<>p_thread or m.body<>p_body or m.asset_ids<>p_assets then raise exception 'Message key conflict';end if;
 return m.id;
end $function$

CREATE OR REPLACE FUNCTION public.icash_set_work_control_before_sms_intake(p_user uuid, p_account uuid, p_action text, p_screening uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prop text;
begin
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_user for update;
 if not found then raise exception 'Account ownership required';end if;
 if p_action in ('pause','resume') then
 update public.icash_accounts set bot_paused=(p_action='pause') where id=p_account;
 elsif p_action in ('takeover','return_to_bot') then
 select snapshot->>'propertyId' into prop from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if prop is null then raise exception 'Property missing';end if;
 insert into public.icash_property_controls(account_id,property_id,manual) values(p_account,prop,p_action='takeover')
 on conflict(account_id,property_id) do update set manual=excluded.manual,updated_at=now();
 if p_action='return_to_bot' then
 update public.icash_handoffs set state='resolved',resolved_at=now() where account_id=p_account and screening_id=p_screening and state<>'resolved';
 -- Returning control never automatically retries a past callback.
 end if;
 else raise exception 'Invalid control';end if;
 insert into public.icash_control_events(account_id,actor_user_id,action,property_id) values(p_account,p_user,p_action,prop);
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_text_before_owner_question(p_account uuid, p_message uuid, p_sender text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare invitation public.icash_sms_inbound_invitations;t public.icash_text_threads;m public.icash_text_messages;d public.icash_deal_files;s public.icash_screening_jobs;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select th.* into t from public.icash_text_threads th join public.icash_text_messages msg on msg.thread_id=th.id and msg.account_id=th.account_id where msg.id=p_message and msg.account_id=p_account;
 if not found then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(t.recipient,74));
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;if not found then return null;end if;
 perform 1 from public.icash_outreach_campaigns where account_id=p_account for share;
 select * into t from public.icash_text_threads where id=t.id and account_id=p_account for update;
 select * into m from public.icash_text_messages where id=p_message and account_id=p_account and thread_id=t.id for update;
 if not found or m.state<>'ready' or m.direction<>'outgoing' then return null;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true' for share;
 if not found then return null;end if;
 select * into s from public.icash_screening_jobs where id=d.screening_id and account_id=p_account and state='complete' for share;
 if not found or s.result->'financialCheck'->>'status' is distinct from 'eligible' or s.completed_at is null or s.completed_at>now() or s.completed_at<now()-interval '24 hours' then return null;end if;

 if exists(select 1 from public.icash_property_controls where account_id=p_account and property_id=s.snapshot->>'propertyId' and manual)
 and not (
  public.icash_manual_handoff_reply(p_account,t.id)
  and not exists(select 1 from public.icash_text_ai_jobs where outgoing_id=p_message and account_id=p_account)
  and not exists(select 1 from public.icash_seller_opener_assignments where message_id=p_message and account_id=p_account)
  and not exists(select 1 from public.icash_sms_inbound_invitations where message_id=p_message and account_id=p_account)
 ) then return null;end if;
 if exists(select 1 from public.icash_text_ai_jobs where outgoing_id=p_message and account_id=p_account) then return null;end if;
 if t.dnc_checked_at>now() then return null;end if;
 if not public.icash_sms_thread_review_current(p_account,t.id,true) then return null;end if;
 if not public.icash_outreach_sms_current(p_account) then return null;end if;
 select * into invitation from public.icash_sms_inbound_invitations where message_id=p_message and account_id=p_account;
 if found then
  if not public.icash_sms_inbound_campaign_current(p_account) then return null;end if;
  select * into t from public.icash_text_threads where id=invitation.thread_id and account_id=p_account;
  if t.id is null or t.sender<>invitation.sender or t.recipient<>invitation.recipient or t.deal_id<>invitation.deal_id or invitation.expires_at<=now() then return null;end if;
  if not exists(select 1 from public.icash_inbound_voice_routes where called_number=invitation.called_number and business_number=p_sender and enabled and reviewed_until>now() and agent_config_hash is not null) then return null;end if;
  if exists(select 1 from public.icash_text_messages where thread_id=t.id and direction='incoming' and id<>invitation.reply_id and created_at>=(select created_at from public.icash_text_messages where id=invitation.reply_id)) then return null;end if;
 end if;
 return public.icash_claim_text_before_campaign(p_account,p_message,p_sender);
end $function$
